window.AUTH=window.AUTH||{};window.AUTH["23-939"]={"d":"23-939","id":"2023/23-939","n":"Trump v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Donald J. Trump","date":"2024-03-19","url":"https://www.supremecourt.gov/DocketPDF/23/23-939/303418/20240319150454815_23-939%20-%20Brief%20for%20Petitioner.pdf","side":"pet","n":53},{"k":"respondent","label":"Brief of respondent United States","date":"2024-04-08","url":"https://www.supremecourt.gov/DocketPDF/23/23-939/306999/20240408191803801_United%20States%20v.%20Trump%20final%20for%20filing.pdf","side":"res","n":73},{"k":"reply","label":"Reply of petitioner Donald J. Trump","date":"2024-04-15","url":"https://www.supremecourt.gov/DocketPDF/23/23-939/307578/20240415133854183_USSC%2023-939%20-%20Reply%20Brief%20of%20Petitioner.pdf","side":"pet","n":40}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r57_2dp3.pdf","tr":true,"items":[{"t":"case","label":"Anderson v. Creighton","cite":"483 U.S. 635","y":1987,"id":"1986/85-1520","sc":1,"by":{"0":"44, 47"},"q":[{"src":"brief","b":0,"text":"A rule is too general if the unlawfulness of the officer’s conduct ‘does not follow immediately from the conclusion that [the rule] was firmly established.’","cite":"483 U.S. at 641"},{"src":"argument","who":"Mr. Sauer","text":"There would have to be -- and -- and I would point the Court to Anderson against Creighton, where the Court said there would be kind of two stages of these further proceedings."}]},{"t":"case","label":"Ashcroft v. al-Kidd","cite":"563 U.S. 731","y":2011,"id":"2010/10-98","sc":1,"by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"[E]xisting precedent must have placed the statutory or constitutional question beyond debate.","cite":"563 U.S. 731, 741"}]},{"t":"case","label":"Barr v. Matteo","cite":"360 U.S. 564","y":1959,"id":"1958/350","sc":1,"by":{"0":"10, 46, 48"},"q":[{"src":"brief","b":0,"text":"[T]he occasions upon which the acts of the head of an executive department will be protected by the privilege are doubtless far broader than in the case of an officer with less sweeping functions. But that is because the higher the post, the broader the range of responsibilities and duties, and the wider the scope of discretion, it entails.","cite":"360 U.S. at 573"}]},{"t":"case","label":"Blassingame v. Trump","cite":"87 F.4th 1","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/87/1/","by":{"0":"9, 44","2":"6"},"q":[{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"`not manifestly or palpably beyond [his] authority,'","cite":"87 F. 4th 1, 13"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"`manifestly or palpably beyond [his] authority.'","cite":"87 F. 4th 1, 13"},{"src":"argument","who":"Justice Gorsuch","text":"Circuit in Blassingame, the chief judge there, joined by the panel, expressed some views about how to segregate private conduct for which no man is above the law from official acts."},{"src":"argument","who":"Mr. Sauer","text":"That sounds to me a lot like Blassingame and especially viewed through the lens of Judge Katsas' separate opinion, and that may not be different than what we're proposing to the Court today."},{"src":"argument","who":"Justice Alito","text":"Well, Blassingame had to do with the difference between official conduct and private conduct, right?"}]},{"t":"case","label":"Bradley v. Fisher","cite":"80 U.S. 335","y":1871,"id":"scdb/1871-141","sc":1,"by":{"0":"48"}},{"t":"case","label":"Butz v. Economou","cite":"438 U.S. 478","y":1978,"id":"1977/76-709","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"The immunity of federal executive officials began as a means of protecting them in the execution of their federal statutory duties from criminal or civil actions based on state law.","cite":"438 U.S. 478, 489"}]},{"t":"case","label":"Chi. & S. Air Lines v. Waterman S. S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"0":"13, 47"},"q":[{"src":"brief","b":0,"text":"beyond the competence of the courts to adjudicate.","cite":"333 U.S. 103, 114"}]},{"t":"case","label":"City of Tahlequa v. Bond","cite":"595 U.S. 9","y":2021,"url":"https://supreme.justia.com/cases/federal/us/595/9/","sc":1,"by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"repeatedly told courts not to define clearly established law at too high a level of generality.","cite":"595 U.S. 9, 12"}]},{"t":"case","label":"Clinton v. Jones","cite":"520 U.S. 681","y":1997,"id":"1996/95-1853","sc":1,"by":{"0":"14-15, 18-19, 27, 43","1":"10, 24, 40"},"q":[{"src":"brief","b":0,"text":"that a President may not be ordered by the Judiciary to perform particular Executive acts.","cite":"520 U.S. 681, 719"},{"src":"brief","b":0,"text":"immunity serves the public interest in enabling such officials to perform their designated functions effectively without fear that a particular decision may give rise to personal liability.","cite":"520 U.S. at 692"},{"src":"brief","b":1,"text":"deems it appropriate to afford the President stronger protection","cite":"520 U.S. at 709"},{"src":"brief","b":1,"text":"when the President takes official action, the Court has the authority to determine whether he has acted within the law.","cite":"520 U.S. at 703"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"sought to encourage energetic, vigorous, decisive, and speedy execution of the laws by placing in the hands of a single, constitutionally indispensable, individual the ultimate authority that, in respect to the other branches, the Constitution divides among many.","cite":"520 U. S. 681, 712"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"rejected at the birth of [our] Republic.","cite":"520 U. S. 681, 697, n. 24"}]},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"by":{"0":"2"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"by":{"0":"38"}},{"t":"case","label":"District of Columbia v. Wesby","cite":"583 U.S. 48","y":2018,"id":"2017/15-1485","sc":1,"by":{"0":"46-47"},"q":[{"src":"brief","b":0,"text":"This requires a high ‘degree of specificity.’","cite":"583 U.S. 48, 63-64"}]},{"t":"case","label":"Edward J. DeBartolo Corp. v. Florida Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"by":{"0":"38","2":"22"},"q":[{"src":"brief","b":2,"text":"where an otherwise acceptable construction of a statute would raise serious constitutional problems, the Court will construe the statute to avoid such problems unless such construction is plainly contrary to the intent of Congress.","cite":"485 U.S. 568, 575"}]},{"t":"case","label":"Ferri v. Ackerman","cite":"444 U.S. 193","y":1979,"id":"1979/78-5981","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"it is in precisely such cases that there exists the greatest public interest in providing an official ‘the maximum ability to deal fearlessly and impartially with’ the duties of his office.","cite":"444 U.S. 193, 203"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`the maximum ability to deal fearlessly and impartially with' the duties of his offce.","cite":"444 U. S. 193, 203"}]},{"t":"case","label":"Filarsky v. Delia","cite":"566 U.S. 377","y":2012,"id":"2011/10-1018","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"own free, unbiased convictions, uninfluenced by any apprehensions.","cite":"566 U.S. 377, 383"}]},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"by":{"0":"8, 12-13, 20, 32, 37, 39","1":"26, 38","2":"6, 20-21"},"q":[{"src":"brief","b":0,"text":"require[s] an express statement by Congress before assuming it intended the President’s performance","cite":"505 U.S. 788, 801"},{"src":"brief","b":0,"text":"no court has authority to direct the President to take an official act.","cite":"505 U.S. at 825"},{"src":"argument","who":"Mr. Sauer","text":"I would quote from what Benjamin Franklin said at the Constitutional Convention, which I think reflects best the Founders' original understanding and intent here, which is, at the Constitutional Convention, Benjamin Franklin said: History provides one example only of a chief magistrate who is subject to public justice, criminal prosecution."},{"src":"argument","who":"Justice Jackson","text":"But, since Benjamin Franklin, everybody has thought, including the presidents who have held the office, that they were taking this office subject to potential criminal prosecution, no?"},{"src":"argument","who":"Mr. Sauer","text":"That's absolutely correct, and that would be consistent both with Franklin and Public Citizen and cases -- a long series of other clear statement rule cases."}]},{"t":"case","label":"Free Enter. Fund v. Public Co. Acct. Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"by":{"0":"24","2":"2, 18"},"q":[{"src":"brief","b":2,"text":"[t]he Framers recognized that, in the long term, structural protections against abuse of power were critical to preserving liberty.","cite":"561 U.S. 477, 501"},{"src":"brief","b":2,"text":"cannot … bind his successors by diminishing their powers.","cite":"561 U.S. at 497"},{"src":"argument","who":"Mr. Sauer","text":"And there's a very telling passage in Free Enterprise Fund where this Court talked about how there's a letter from James Madison to Thomas Jefferson at the time of the founding where Madison said, hey, the -- as to the removal power, they did not expressly take this away, so the 1789 Congress understood that it was left in place."}]},{"t":"case","label":"Gregoire v. Biddle","cite":"177 F.2d 579","y":1949,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/177/579/","by":{"0":"27, 48"},"q":[{"src":"brief","b":0,"text":"[T]o submit all officials, the innocent as well as the guilty, to the burden of a trial and to the inevitable danger of its outcome, would dampen the ardor of all but the most resolute.","cite":"177 F.2d 579, 581"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`to the burden of a trial and to the inevitable danger of its outcome, would dampen the ardor of all but the most resolute.'","cite":"177 F. 2d 579, 581"}]},{"t":"case","label":"Hammerschmidt v. United States","cite":"265 U.S. 182","y":1924,"id":"scdb/1923-145","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"means primarily to cheat the government out of property or money.","cite":"265 U.S. 182, 188"}]},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"by":{"0":"45, 48, 50"},"q":[{"src":"brief","b":0,"text":"for acts within the ‘outer perimeter’ of his official responsibility.","cite":"457 U.S. at 756"},{"src":"brief","b":0,"text":"absolute Presidential immunity from [civil] damages liability for acts within the ‘outer perimeter’ of his official responsibility.","cite":"457 U.S. at 756"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"occupies a unique position in the constitutional scheme,","cite":"457 U. S., at 749"}]},{"t":"case","label":"Kendall v. U.S. ex rel. Stokes","cite":"37 U.S. 524","y":1838,"id":"scdb/1838-042","sc":1,"by":{"0":"12, 18","2":"6"},"q":[{"src":"brief","b":0,"text":"The executive power is vested in a President; and as far as his powers are derived from the constitution, he is beyond the reach of any other department, except in the mode prescribed by the constitution through the impeaching power.","cite":"37 U.S. 524, 610"}]},{"t":"case","label":"Martin v. Mott","cite":"25 U.S. 19","y":1827,"id":"scdb/1827-009","sc":1,"by":{"0":"11-12, 15, 18, 30, 47","2":"5-6"},"q":[{"src":"brief","b":0,"text":"upon the proofs submitted to a jury.","cite":"25 U.S. at 32"},{"src":"argument","who":"Mr. Sauer","text":"But I want to address a more higher-level point, a fundamental point, which is that, as Justice Alito's question indicated, there's a whole series of structural checks other than criminal prosecution that are designed to deter these kind of, you know, outlandish scenarios or extraordinarily obviously illegal things, and that's been viewed in this Court's opinions going all the way back to at least Martin against Mott."},{"src":"argument","who":"Mr. Sauer","text":"All the structural checks that are identified in Fitzgerald and a whole series of this Court's cases that go back to Martin against Mott, for example, impeachment, oversight by Congress, public oversight."}]},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"by":{"0":"24"},"q":[{"src":"argument","who":"Mr. Dreeben","text":"So that raises a Supremacy Clause issue, and the Court would run a Supremacy Clause analysis that would probably start with basic principles like McCulloch versus Maryland."}]},{"t":"case","label":"MCI Telecommunications Corp. v. American Telephone & Telegraph Co.","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"by":{"0":"38"}},{"t":"case","label":"Mississippi v. Johnson","cite":"71 U.S. 475","y":1866,"id":"1850-1900/71us475","sc":1,"by":{"0":"12, 31-32","2":"6"},"q":[{"src":"brief","b":0,"text":"which nothing is left to discretion.","cite":"71 U.S. at 498"},{"src":"brief","b":0,"text":"First, more formally, when a federal court enjoins the conduct of a subordinate executive officer, it may frustrate the President’s will in a specific instance, but it does not seize the very reins of the executive branch by exercising control over ‘the executive department’ itself.","cite":"71 U.S. at 500"},{"src":"argument","who":"Mr. Sauer","text":"I see all the evidence going the other way. Marbury against Madison, Mississippi against Johnson discussed this broad immunity principle that naturally extends to the --"},{"src":"argument","who":"Mr. Sauer","text":"The -- we have the historical precedent we cite in the lower courts of President Grant sending federal troops to Louisiana and Mississippi in 1876 to make sure that the Republican electors got certified in those two cases, which delivered the election to Rutherford B."}]},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"by":{"0":"3, 28, 37","1":"19","2":"22"},"q":[{"src":"brief","b":0,"text":"deeply wounds the President, by substantially reducing the President’s ability to protect himself.","cite":"487 U.S. 654, 713"},{"src":"brief","b":0,"text":"While the separation of powers may prevent us from righting every wrong, it does so in order to ensure that we do not lose liberty.","cite":"487 U.S. at 710"},{"src":"brief","b":2,"text":"While the separation of powers may prevent us from righting every wrong, it does so in order to ensure that we do not lose liberty.","cite":"487 U.S. at 710"},{"src":"brief","b":2,"text":"it is not an absolutely overriding value.","cite":"487 U.S. at 732"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"[I]nvestigation and prosecution of crimes is a quintessentially executive function.","cite":"487 U. S. 654, 706"},{"src":"opinion","who":"Justice Thomas, concurring","text":"While the separation of powers may prevent us from righting every wrong, it does so in order to ensure that we do not lose liberty.","cite":"487 U. S. 654, 710–711"},{"src":"opinion","who":"Justice Thomas, concurring","text":"the absolutely central guarantee of a just Government","cite":"487 U. S., at 697"},{"src":"argument","who":"Mr. Sauer","text":"As Justice Scalia said in Morrison against Olson, the separation of powers prevents us from righting every wrong, but it does so that we do not lose liberty."},{"src":"argument","who":"Justice Kavanaugh","text":"Second, like Justice Gorsuch, I'm not focused on the here and now of this case. I'm very concerned about the future. And I think one of the Court's biggest mistakes was Morrison versus Olson."},{"src":"argument","who":"Justice Kavanaugh","text":"That's the concern going forward, is that the -- the system will -- when -- when former presidents are subject to prosecution and the history of Morrison versus Olson tells us it's not going to stop, it's going to -- it's going to cycle back and be used against the current president or the next president or -- and the next president and the next president after that."}]},{"t":"case","label":"Moyer v. Peabody","cite":"212 U.S. 78","y":1909,"id":"scdb/1908-062","sc":1,"by":{"0":"46"}},{"t":"case","label":"Newdow v. Roberts","cite":"603 F.3d 1002","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/603/1002/","by":{"0":"14"},"q":[{"src":"brief","b":0,"text":"With regard to the President, courts do not have jurisdiction to enjoin him, and have never submitted the President to declaratory relief.","cite":"603 F.3d 1002, 1013"}]},{"t":"case","label":"NFIB v. OSHA","cite":"595 U.S. 109","y":2022,"url":"https://supreme.justia.com/cases/federal/us/595/109/","sc":1,"by":{"0":"8, 24, 38"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"by":{"0":"2-4, 7-8, 10, 14-16, 19-20, 24-27, 28-29, 32, 35-36, 41-45, 48, 50","1":"5, 9, 14, 18-20, 39, 40, 42","2":"1, 5-6, 8, 13, 16, 23"},"q":[{"src":"brief","b":0,"text":"for acts within the ‘outer perimeter’ of his official responsibility.","cite":"457 U.S. at 756"},{"src":"brief","b":0,"text":"absolute Presidential immunity from [civil] damages liability for acts within the ‘outer perimeter’ of his official responsibility.","cite":"457 U.S. at 756"},{"src":"brief","b":1,"text":"occupies a unique position in the constitutional scheme.","cite":"457 U.S. 731, 749"},{"src":"brief","b":1,"text":"the Presidency did not exist through most of the development of common law.","cite":"457 U.S. at 747"},{"src":"brief","b":2,"text":"The President’s unique status … distinguishes him from other executive officials.","cite":"457 U.S. at 750"},{"src":"brief","b":2,"text":"should not be under an apprehension that the motives that control his official conduct may, at any time, become the subject of inquiry.","cite":"457 U.S. at 745"}]},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"[T]he longstanding ‘practice of the government,’ can inform our determination of ‘what the law is.’","cite":"573 U.S. 513, 525"}]},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"by":{"0":"46","2":"24"},"q":[{"src":"brief","b":2,"text":"an immunity from suit rather than a mere defense to liability ... it is effectively lost if a case is erroneously permitted to go to trial.","cite":"555 U.S. 223, 231"}]},{"t":"case","label":"Pierson v. Ray","cite":"386 U.S. 547","y":1967,"id":"1966/79","sc":1,"by":{"0":"26, 38, 48"},"q":[{"src":"brief","b":0,"text":"[A] President must concern himself with matters likely to ‘arouse the most intense feelings,’","cite":"386 U.S. 547, 554"}]},{"t":"case","label":"Public Citizen v. U.S. Dep’t of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"by":{"0":"8, 37-38","1":"26"},"q":[{"src":"brief","b":0,"text":"loath to conclude that Congress intended to press ahead into dangerous constitutional thickets in the absence of firm evidence that it courted those perils,","cite":"491 U.S. 440, 466"},{"src":"brief","b":0,"text":"When the validity of an act of the Congress is drawn in question, and even if a serious doubt of constitutionality is raised, it is a cardinal principle that this Court will first ascertain whether a construction of the statute is fairly possible by which the question may be avoided.","cite":"491 U.S. at 465"}]},{"t":"case","label":"Scheuer v. Rhodes","cite":"416 U.S. 232","y":1974,"id":"1973/72-914","sc":1,"by":{"0":"38, 46"}},{"t":"case","label":"Seila Law, LLC v. CFPB","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"by":{"0":"24","1":"11","2":"1, 3, 7, 10, 16"},"q":[{"src":"brief","b":2,"text":"The Framers deemed an energetic executive essential to ‘the protection of the community against foreign attacks,’ ‘the steady administration of the laws,’ ‘the protection of property,’ and ‘the security of liberty.’","cite":"140 S. Ct. 2183, 2203"},{"src":"brief","b":2,"text":"Under our Constitution, the ‘executive Power’— all of it—is ‘vested in a President’ … .","cite":"140 S. Ct. at 2191"},{"src":"argument","who":"Mr. Sauer","text":"The strongest possible case in our view is what you've described as kind of the core executive powers, the unrestrictable powers within the meaning of Seila Law."},{"src":"argument","who":"Mr. Dreeben","text":"So, here -- here, I might need to differentiate between the principal officers that this Court in cases like Myers and Seila Law has regarded as having constitutional status of being removable at will from inferior officers, where Congress does have some regulatory latitude to impose restrictions on removal."}]},{"t":"case","label":"Solid Waste Agency of N. Cook Cnty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"by":{"0":"38"}},{"t":"case","label":"Spalding v. Vilas","cite":"161 U.S. 483","y":1896,"id":"scdb/1895-154","sc":1,"by":{"0":"25, 41, 48","1":"43","2":"14"},"q":[{"src":"brief","b":0,"text":"[t]he doctrine which holds a judge exempt from a civil suit or indictment for any act done or omitted to be done by him, sitting as judge, has a deep root in the common law.","cite":"161 U.S. 483, 494"}]},{"t":"case","label":"Trump v. Anderson","cite":"144 S. Ct. 662","y":2024,"id":"2023/23-719","sc":1,"by":{"0":"7, 24","1":"17","2":"10"},"q":[{"src":"brief","b":0,"text":"a telling indication of a severe constitutional problem with the asserted power.","cite":"144 S. Ct. 662, 669"},{"src":"brief","b":0,"text":"Such a lack of historical precedent is generally a ‘telling indication’ of a ‘severe constitutional problem’ with the asserted power.","cite":"144 S. Ct. at 669"}]},{"t":"case","label":"Trump v. Mazars USA, LLP","cite":"591 U.S. 848","y":2020,"id":"2019/19-715","sc":1,"by":{"0":"16, 43","1":"9"},"q":[{"src":"brief","b":0,"text":"The President is the only person who alone composes a branch of government. As a result, there is not always a clear line between his personal and official affairs.","cite":"591 U.S. at 868"},{"src":"brief","b":1,"text":"the only person who alone composes a branch of government.","cite":"591 U.S. 848, 868"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"the only Pperasogn wehoPalornoe coomfpPosees anbdranicnh gof gPoveurnbmleinct,","cite":"591 U. S. 848, 868"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"there is not always a clear line between [the President's] personal and offcial affairs.","cite":"591 U. S., at 868"}]},{"t":"case","label":"Trump v. Vance","cite":"140 S. Ct. 2412","y":2020,"id":"2019/19-635","sc":1,"by":{"0":"3, 14-15, 17, 26-27, 43","1":"12, 14, 15, 22, 40, 42","2":"5"},"q":[{"src":"brief","b":0,"text":"decisionmaking process with respect to official acts,","cite":"140 S. Ct. 2412, 2426"},{"src":"brief","b":0,"text":"the distortion of the Executive’s ‘decisionmaking process’ with respect to official acts that would stem from ‘worry as to the possibility of’","cite":"140 S. Ct. at 2426"},{"src":"brief","b":2,"text":"distortion of the Executive’s ‘decisionmaking process’ with respect to official acts,","cite":"140 S. Ct. 2412, 2426"}]},{"t":"case","label":"United States v. Johnson","cite":"383 U.S. 169","y":1966,"id":"1965/25","sc":1,"by":{"0":"25, 41","1":"44","2":"14, 23"},"q":[{"src":"brief","b":0,"text":"was not born primarily of a desire to avoid private suits … but rather to prevent intimidation by the executive and accountability before a possibly hostile judiciary.","cite":"383 U.S. 169, 181"},{"src":"brief","b":1,"text":"the criminal and civil law to suppress and intimidate critical legislators,","cite":"383 U.S. 169, 178"},{"src":"brief","b":2,"text":"The claim of an unworthy purpose does not destroy the privilege.","cite":"383 U.S. at 180"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"`any conspiracy for the purpose of impairing, obstructing or defeating the lawful function of any department of Government.'","cite":"383 U. S. 169, 172"}]},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"by":{"0":"24","1":"20"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"by":{"0":"39"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Clinton","cite":"568 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"by":{"0":"44"}},{"t":"usc","label":"18 U.S.C. § 241","url":"https://www.law.cornell.edu/uscode/text/18/241","stext":{"head":"§241. Conspiracy against rights","paras":[[0,"If two or more persons conspire to injure, oppress, threaten, or intimidate any person in any State, Territory, Commonwealth, Possession, or District in the free exercise or enjoyment of any right or privilege secured to him by the Constitution or laws of the United States, or because of his having so exercised the same; or"],[0,"If two or more persons go in disguise on the highway, or on the premises of another, with intent to prevent or hinder his free exercise or enjoyment of any right or privilege so secured—"],[0,"They shall be fined under this title or imprisoned not more than ten years, or both; and if death results from the acts committed in violation of this section or if such acts include kidnapping or an attempt to kidnap, aggravated sexual abuse or an attempt to commit aggravated sexual abuse, or an attempt to kill, they shall be fined under this title or imprisoned for any term of years or for life, or both, or may be sentenced to death."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/241?type=usc&year=mostrecent&link-type=html"},"by":{"0":"39","1":"25"},"q":[{"src":"brief","b":1,"text":"injure [or] oppress * * * the free exercise or enjoyment","cite":"18 U.S.C. 241"}]},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","stext":{"head":"§371. Conspiracy to commit offense or to defraud United States","paras":[[0,"If two or more persons conspire either to commit any offense against the United States, or to defraud the United States, or any agency thereof in any manner or for any purpose, and one or more of such persons do any act to effect the object of the conspiracy, each shall be fined under this title or imprisoned not more than five years, or both."],[0,"If, however, the offense, the commission of which is the object of the conspiracy, is a misdemeanor only, the punishment for such conspiracy shall not exceed the maximum punishment provided for such misdemeanor."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/371?type=usc&year=mostrecent&link-type=html"},"by":{"0":"39","1":"25","2":"17"}},{"t":"usc","label":"18 U.S.C. § 1512","url":"https://www.law.cornell.edu/uscode/text/18/1512","subs":["(c)(2)","(k)","(c)"],"stext":{"head":"§1512. Tampering with a witness, victim, or an informant","paras":[[0,"(a)(1) Whoever kills or attempts to kill another person, with intent to—"],[1,"(A) prevent the attendance or testimony of any person in an official proceeding;"],[1,"(B) prevent the production of a record, document, or other object, in an official proceeding; or"],[1,"(C) prevent the communication by any person to a law enforcement officer or judge of the United States of information relating to the commission or possible commission of a Federal offense or a violation of conditions of probation, parole, or release pending judicial proceedings;"],[0,"shall be punished as provided in paragraph (3)."],[0,"(2) Whoever uses physical force or the threat of physical force against any person, or attempts to do so, with intent to—"],[1,"(A) influence, delay, or prevent the testimony of any person in an official proceeding;"],[1,"(B) cause or induce any person to—"],[2,"(i) withhold testimony, or withhold a record, document, or other object, from an official proceeding;"],[2,"(ii) alter, destroy, mutilate, or conceal an object with intent to impair the integrity or availability of the object for use in an official proceeding;"],[2,"(iii) evade legal process summoning that person to appear as a witness, or to produce a record, document, or other object, in an official proceeding; or"],[2,"(iv) be absent from an official proceeding to which that person has been summoned by legal process; or"],[1,"(C) hinder, delay, or prevent the communication to a law enforcement officer or judge of the United States of information relating to the commission or possible commission of a Federal offense or a violation of conditions of probation, supervised release, parole, or release pending judicial proceedings;"],[0,"shall be punished as provided in paragraph (3)."],[0,"(3) The punishment for an offense under this subsection is—"],[1,"(A) in the case of a killing, the punishment provided in sections 1111 and 1112;"],[1,"(B) in the case of—"],[2,"(i) an attempt to murder; or"],[2,"(ii) the use or attempted use of physical force against any person;"],[1,"imprisonment for not more than 30 years; and"],[1,"(C) in the case of the threat of use of physical force against any person, imprisonment for not more than 20 years."],[0,"(b) Whoever knowingly uses intimidation, threatens, or corruptly persuades another person, or attempts to do so, or engages in misleading conduct toward another person, with intent to—"],[1,"(1) influence, delay, or prevent the testimony of any person in an official proceeding;"],[1,"(2) cause or induce any person to—"],[2,"(A) withhold testimony, or withhold a record, document, or other object, from an official proceeding;"],[2,"(B) alter, destroy, mutilate, or conceal an object with intent to impair the object's integrity or availability for use in an official proceeding;"],[2,"(C) evade legal process summoning that person to appear as a witness, or to produce a record, document, or other object, in an official proceeding; or"],[2,"(D) be absent from an official proceeding to which such person has been summoned by legal process; or"],[1,"(3) hinder, delay, or prevent the communication to a law enforcement officer or judge of the United States of information relating to the commission or possible commission of a Federal offense or a violation of conditions of probation 1 supervised release,,1 parole, or release pending judicial proceedings;"],[0,"shall be fined under this title or imprisoned not more than 20 years, or both."],[0,"(c) Whoever corruptly—"],[1,"(1) alters, destroys, mutilates, or conceals a record, document, or other object, or attempts to do so, with the intent to impair the object's integrity or availability for use in an official proceeding; or"],[1,"(2) otherwise obstructs, influences, or impedes any official proceeding, or attempts to do so,"],[0,"shall be fined under this title or imprisoned not more than 20 years, or both."],[0,"(d) Whoever intentionally harasses another person and thereby hinders, delays, prevents, or dissuades any person from—"],[1,"(1) attending or testifying in an official proceeding;"],[1,"(2) reporting to a law enforcement officer or judge of the United States the commission or possible commission of a Federal offense or a violation of conditions of probation 1 supervised release,,1 parole, or release pending judicial proceedings;"],[1,"(3) arresting or seeking the arrest of another person in connection with a Federal offense; or"],[1,"(4) causing a criminal prosecution, or a parole or probation revocation proceeding, to be sought or instituted, or assisting in such prosecution or proceeding;"],[0,"or attempts to do so, shall be fined under this title or imprisoned not more than 3 years, or both."],[0,"(e) In a prosecution for an offense under this section, it is an affirmative defense, as to which the defendant has the burden of proof by a preponderance of the evidence, that the conduct consisted solely of lawful conduct and that the defendant's sole intention was to encourage, induce, or cause the other person to testify truthfully."],[0,"(f) For the purposes of this section—"],[1,"(1) an official proceeding need not be pending or about to be instituted at the time of the offense; and"],[1,"(2) the testimony, or the record, document, or other object need not be admissible in evidence or free of a claim of privilege."],[0,"(g) In a prosecution for an offense under this section, no state of mind need be proved with respect to the circumstance—"],[1,"(1) that the official proceeding before a judge, court, magistrate judge, grand jury, or government agency is before a judge or court of the United States, a United States magistrate judge, a bankruptcy judge, a Federal grand jury, or a Federal Government agency; or"],[1,"(2) that the judge is a judge of the United States or that the law enforcement officer is an officer or employee of the Federal Government or a person authorized to act for or on behalf of the Federal Government or serving the Federal Government as an adviser or consultant."],[0,"(h) There is extraterritorial Federal jurisdiction over an offense under this section."],[0,"(i) A prosecution under this section or section 1503 may be brought in the district in which the official proceeding (whether or not pending or about to be instituted) was intended to be affected or in the district in which the conduct constituting the alleged offense occurred."],[0,"(j) If the offense under this section occurs in connection with a trial of a criminal case, the maximum term of imprisonment which may be imposed for the offense shall be the higher of that otherwise provided by law or the maximum term that could have been imposed for any offense charged in such case."],[0,"(k) Whoever conspires to commit any offense under this section shall be subject to the same penalties as those prescribed for the offense the commission of which was the object of the conspiracy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1512?type=usc&year=mostrecent&link-type=html"},"by":{"0":"39, 39","1":"26, 26, 26","2":"17"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"const","label":"Article I, Section 3, Clause 7","text":"Judgment in Cases of Impeachment shall not extend further than to removal from Office, and disqualification to hold and enjoy any Office of honor, Trust or Profit under the United States: but the Party convicted shall nevertheless be liable and subject to Indictment, Trial, Judgment and Punishment, according to Law.","by":{"0":"16, 22, 35"}},{"t":"const","label":"Article II, Section 1","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"]],"by":{"0":"10, 13, 26","2":"3"}},{"t":"usc","label":"28 U.S.C. § 458","url":"https://www.law.cornell.edu/uscode/text/28/458","stext":{"head":"§458. Relative of justice or judge ineligible to appointment","paras":[[0,"(a)(1) No person shall be appointed to or employed in any office or duty in any court who is related by affinity or consanguinity within the degree of first cousin to any justice or judge of such court."],[0,"(2) With respect to the appointment of a judge of a court exercising judicial power under article III of the United States Constitution (other than the Supreme Court), subsection (b) shall apply in lieu of this subsection."],[0,"(b)(1) In this subsection, the term—"],[1,"(A) \"same court\" means—"],[2,"(i) in the case of a district court, the court of a single judicial district; and"],[2,"(ii) in the case of a court of appeals, the court of appeals of a single circuit; and"],[1,"(B) \"member\"—"],[2,"(i) means an active judge or a judge retired in senior status under section 371(b); and"],[2,"(ii) shall not include a retired judge, except as described under clause (i)."],[0,"(2) No person may be appointed to the position of judge of a court exercising judicial power under article III of the United States Constitution (other than the Supreme Court) who is related by affinity or consanguinity within the degree of first cousin to any judge who is a member of the same court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/458?type=usc&year=mostrecent&link-type=html"},"by":{"0":"38","1":"27, 28"},"q":[{"src":"brief","b":0,"text":"the well-settled principle that statutes that do not expressly apply to the President must be construed as not applying to the President if such application would involve a possible conflict with the President’s constitutional prerogatives.","cite":"28 U.S.C. § 458"},{"src":"brief","b":1,"text":"doing so would raise a serious question under the separation of powers.","cite":"28 U.S.C. § 458"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"possible confict with the President's constitutional prerogatives.","cite":"28 U. S. C. § 458"},{"src":"opinion","who":"Justice Barrett, concurring in part","text":"raise serious constitutional questions relating to the President's constitutional authority.","cite":"28 U. S. C. § 458"}]},{"t":"case","label":"Ashwander v. TVA","cite":"297 U.S. 288","y":1936,"id":"1900-1940/297us288","sc":1,"by":{"1":"45"}},{"t":"case","label":"Burdick v. United States","cite":"236 U.S. 79","y":1915,"id":"scdb/1914-243","sc":1,"by":{"1":"16"}},{"t":"case","label":"Cheney v. United States Dist. Ct.","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"by":{"1":"19, 22"},"q":[{"src":"brief","b":1,"text":"commitment to the rule of law * * * is nowhere more profoundly manifest","cite":"542 U.S. 367, 384"}]},{"t":"case","label":"Dames & Moore v. Regan","cite":"453 U.S. 654","y":1981,"id":"1980/80-2078","sc":1,"by":{"1":"11, 39"},"q":[{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"confne the opinion only to the very questions necessary to decision of the case.","cite":"453 U. S. 654, 661"}]},{"t":"case","label":"Dennis v. Sparks","cite":"449 U.S. 24","y":1980,"id":"1980/79-1186","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"subject to criminal prosecutions as are other citizens.","cite":"449 U.S. 24, 31"}]},{"t":"case","label":"Dowling v. United States","cite":"493 U.S. 342","y":1990,"id":"1989/88-6025","sc":1,"by":{"1":"48"}},{"t":"case","label":"Garcetti v. Ceballos","cite":"547 U.S. 410","y":2006,"id":"2005/04-473","sc":1,"by":{"1":"47"}},{"t":"case","label":"Gravel v. United States","cite":"408 U.S. 606","y":1972,"id":"1971/71-1017","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"On the contrary, the judicially fashioned doctrine of official immunity does not reach ‘so far as to immunize criminal conduct proscribed by an Act of Congress.’","cite":"408 U.S. 606, 627"}]},{"t":"case","label":"Hamdan v. Rumsfeld","cite":"548 U.S. 557","y":2006,"id":"2005/05-184","sc":1,"by":{"1":"12"}},{"t":"case","label":"Huddleston v. United States","cite":"485 U.S. 681","y":1988,"id":"1987/87-6","sc":1,"by":{"1":"48"},"q":[{"src":"brief","b":1,"text":"is to be considered only for the proper purpose for which it was admitted.","cite":"485 U.S. 681, 691-692"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"considered only for the proper purpose for which it was admitted.","cite":"485 U. S. 681, 691– 692"}]},{"t":"case","label":"Imbler v. Pachtman","cite":"424 U.S. 409","y":1976,"id":"1975/74-5435","sc":1,"by":{"1":"43"}},{"t":"case","label":"Manhattan Cmty. Access Corp. v. Halleck","cite":"587 U.S. 802","y":2019,"id":"2018/17-1702","sc":1,"by":{"1":"47"}},{"t":"case","label":"Medellin v. Texas","cite":"552 U.S. 491","y":2008,"id":"2007/06-984","sc":1,"by":{"1":"12, 39"}},{"t":"case","label":"Nardone v. United States","cite":"302 U.S. 379","y":1937,"id":"scdb/1937-010","sc":1,"by":{"1":"25"},"q":[{"src":"argument","who":"Mr. Dreeben","text":"They apply to whoever. There's no ambiguity in those phrases. This Court in Nardone versus United States concluded that similar words, \"any person\" --"}]},{"t":"case","label":"Nixon v. Administrator of Gen. Servs.","cite":"433 U.S. 425","y":1977,"id":"1976/75-1605","sc":1,"by":{"1":"12, 18"},"q":[{"src":"brief","b":1,"text":"prevent the Executive Branch from accomplishing its constitutionally assigned functions.","cite":"433 U.S. 425, 443"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"justifed by an overriding need to promote objectives within the constitutional authority of Congress.","cite":"433 U. S. 425, 443"}]},{"t":"case","label":"Nixon v. United States","cite":"506 U.S. 224","y":1993,"id":"1992/91-740","sc":1,"by":{"1":"33"}},{"t":"case","label":"O’Shea v. Littleton","cite":"414 U.S. 488","y":1974,"id":"1973/72-953","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"never held that the performance of the duties of judicial, legislative, or executive officers, requires or contemplates the immunization of otherwise criminal deprivation of constitutional rights.","cite":"414 U.S. 488, 503"}]},{"t":"case","label":"Sale v. Haitian Centers Council","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"by":{"1":"30"}},{"t":"case","label":"Trump v. Hawaii","cite":"585 U.S. 667","y":2018,"id":"2017/17-965","sc":1,"by":{"1":"39","2":"7"},"q":[{"src":"brief","b":2,"text":"extraordinary power to speak to his fellow citizens and on their behalf.","cite":"585 U.S. 667, 701"}]},{"t":"case","label":"United States v. Armstrong","cite":"517 U.S. 456","y":1996,"id":"1995/95-157","sc":1,"by":{"1":"20, 21"},"q":[{"src":"brief","b":1,"text":"clear evidence to the contrary, courts presume that [federal prosecutors] have properly discharged their official duties.","cite":"517 U.S. at 464"}]},{"t":"case","label":"United States v. Blagojevich","cite":"794 F.3d 729","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/794/729/","by":{"1":"41"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 30","y":1807,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/30/","by":{"1":"13"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"the law does not discriminate between the president and a private citizen.","cite":"25 F. Cas. 30, 34"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"ought not on light ground to be forced into public view.","cite":"25 F. Cas., at 37"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"be required to proceed against the president as against an ordinary individual.","cite":"25 F. Cas., at 192"}]},{"t":"case","label":"United States v. Butenko","cite":"494 F.2d 593","y":1974,"url":"https://www.courtlistener.com/c/F.2d/494/593/","by":{"1":"30"}},{"t":"case","label":"Unites States v. Claiborne","cite":"727 F.2d 842","y":1984,"url":"https://www.courtlistener.com/c/F.2d/727/842/","by":{"1":"33"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"by":{"1":"22"}},{"t":"case","label":"United States v. Haldeman","cite":"559 F.2d 31","y":1976,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/559/31/","by":{"1":"15, 47"},"q":[{"src":"argument","who":"Mr. Dreeben","text":"The Watergate smoking gun tape involved President Nixon and H.R. Haldeman talking about and then deciding to use the CIA to give a bogus story to the FBI to shut down a criminal investigation."}]},{"t":"case","label":"United States v. Hastings","cite":"681 F.2d 706","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/681/706/","by":{"1":"33"}},{"t":"case","label":"United States v. Isaacs","cite":"493 F.2d 1124","y":1974,"url":"https://www.courtlistener.com/c/F.2d/493/1124/","by":{"1":"33"}},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 259","y":1997,"id":"1996/95-1717","sc":1,"by":{"1":"23"},"q":[{"src":"argument","who":"Mr. Dreeben","text":"But the idea that a decision that was made and ultimately endorsed by this Court, perhaps wrongly in the Korematsu case, would support criminal prosecution under 241, which requires under United States versus Lanier that the right had been made specific so that there is notice to the president, I don't think that would have been satisfied."}]},{"t":"case","label":"United States v. Lee","cite":"106 U.S. 196","y":1882,"id":"scdb/1882-052","sc":1,"by":{"1":"12"},"q":[{"src":"opinion","who":"Justice Jackson, dissenting","text":"No man in this country is so high that he is above the law. No offcer of the law may set that law at defance with impunity. All the offcers of the government, from the highest to the lowest, are creatures of the law, and are bound to obey it.","cite":"106 U. S. 196, 220"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"is the only supreme power in our system of government, and every man who by accepting offce participates in its functions is only the more strongly bound to submit to that supremacy, and to observe the limitations which it imposes upon the exercise of the authority which it gives.","cite":"106 U. S., at 220"}]},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"by":{"1":"12, 15, 16, 19, 21, 22, 30, 33"},"q":[{"src":"brief","b":1,"text":"the primary constitutional duty of the Judicial Branch [is] to do justice in criminal prosecutions.","cite":"418 U.S. at 707"},{"src":"brief","b":1,"text":"the power to conduct the criminal litigation of the United States Government,","cite":"418 U.S. at 694"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"constitutional duty of the Judicial Branch to do justice in criminal prosecutions.","cite":"418 U. S. 683, 703, 707"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"the silence of the Constitution on this score is not dispositive.","cite":"418 U. S. 683, 706, n. 16"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"primary constitutional duty of the Judicial Branch to do justice in criminal prosecutions.","cite":"418 U. S. 683, 707"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"`[t]he chance that now and then there may be found some timid soul who will take counsel of his fears and give way to their repressive power is too remote and shadowy to shape the course of justice.'","cite":"418 U. S., at 712, n. 20"}]},{"t":"case","label":"United States v. Rostenkowski","cite":"59 F.3d 1291","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/59/1291/","by":{"1":"48"}},{"t":"case","label":"United States v. Sun-Diamond Growers","cite":"526 U.S. 398","y":1999,"id":"1998/98-131","sc":1,"by":{"1":"28"},"q":[{"src":"argument","who":"Mr. Dreeben","text":"In United States versus Sun-Diamond, a case about gratuities that the Court is probably familiar with, Justice Scalia wrote an opinion for a unanimous Court in which he used a hypothetical about what would happen if the president received a sports replica jersey at a typical White House event."}]},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"a person of ordinary intelligence fair notice of what is prohibited.","cite":"553 U.S. 285, 304"}]},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"serv[es] 7 Reliance on Special Counsels in sensitive matters provides further safeguards by balancing independence in day-to-day prosecutorial decisionmaking with ultimate accountability in the Attorney General. See 64 Fed. Reg. 37,038 (July 9, 1999). as a kind of buffer or referee between the Government and the people.","cite":"504 U.S. 36, 47"},{"src":"opinion","who":"Justice Sotomayor, dissenting","text":"buffer or referee between the Government and the people,","cite":"504 U. S. 36, 47"}]},{"t":"case","label":"Wayte v. United States","cite":"470 U.S. 598","y":1985,"id":"1984/83-1292","sc":1,"by":{"1":"22"},"q":[{"src":"argument","who":"Mr. Dreeben","text":"A politically driven prosecution would violate the Constitution under Wayte versus United States. It's not something within the arsenal of prosecutors to do."}]},{"t":"case","label":"Wisconsin v. Mitchell","cite":"508 U.S. 476","y":1993,"id":"1992/92-515","sc":1,"by":{"1":"48"},"q":[{"src":"argument","who":"Mr. Dreeben","text":"That's the usual rule with protected speech, for example, under Wisconsin versus Mitchell. My friend analogizes this to the Speech or Debate Clause, but we don't think the Speech or Debate Clause has any applicability here."}]},{"t":"case","label":"Yates v. Lansing","cite":"5 Johns. 282","y":1810,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Johns./5/282/","by":{"1":"43"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"by":{"1":"4, 10-12, 39, 40","2":"2, 4, 6"},"q":[{"src":"brief","b":1,"text":"acts pursuant to an express or implied authorization of Congress.","cite":"343 U.S. at 635"},{"src":"brief","b":2,"text":"[t]he tendency is strong to emphasize transient results … and lose sight of enduring consequences upon the balanced power structure of our Republic.","cite":"343 U.S. 579, 634"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"enduring consequences upon the balanced power structure of our Republic.","cite":"343 U. S. 579, 634"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"disabling the Congress from acting upon the subject.","cite":"343 U. S., at 637"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"The Framers, however, did not make the Page Proof Pending Publication judiciary the overseer of our government.","cite":"343 U. S. 579, 594"},{"src":"argument","who":"Mr. Dreeben","text":"The core kinds of activities that the Court has acknowledged are the things that I would run through the Youngstown analysis. And it's a pretty small set, but things like the pardon power, the power to recognize foreign nations, the power to veto legislation, the power to make appointments, these are things that the Constitution specifically allocates to the president."},{"src":"argument","who":"Mr. Dreeben","text":"There are as-applied constitutional challenges that you run through the Youngstown framework and this Court's customary method of analysis, and you determine whether there's a infringement of Article II."}]},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"by":{"1":"30"}},{"t":"case","label":"Zivotofsky v. Kerry","cite":"576 U.S. 1","y":2015,"id":"2014/13-628","sc":1,"by":{"1":"11, 30","2":"3, 6-8"},"q":[{"src":"brief","b":2,"text":"includes all powers originally understood as falling within the ‘executive Power’ of the Federal Government.","cite":"576 U.S. 1, 35"},{"src":"brief","b":2,"text":"originally understood as falling within the ‘executive Power’ of the Federal Government.","cite":"576 U.S. at 35"}]},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"1":"47, 48"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"1":"3, 21"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"1":"22"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(b)"],"by":{"1":"26","2":"20"}},{"t":"law","label":"Federal Advisory Committee Act, Pub. L. No. 92-463","url":"https://www.govinfo.gov/link/statute/86/770","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/18/201","stext":{"head":"§201. Bribery of public officials and witnesses","paras":[[0,"(a) For the purpose of this section—"],[1,"(1) the term \"public official\" means Member of Congress, Delegate, or Resident Commissioner, either before or after such official has qualified, or an officer or employee or person acting for or on behalf of the United States, or any department, agency or branch of Government thereof, including the District of Columbia, in any official function, under or by authority of any such department, agency, or branch of Government, or a juror;"],[1,"(2) the term \"person who has been selected to be a public official\" means any person who has been nominated or appointed to be a public official, or has been officially informed that such person will be so nominated or appointed; and"],[1,"(3) the term \"official act\" means any decision or action on any question, matter, cause, suit, proceeding or controversy, which may at any time be pending, or which may by law be brought before any public official, in such official's official capacity, or in such official's place of trust or profit."],[0,"(b) Whoever—"],[1,"(1) directly or indirectly, corruptly gives, offers or promises anything of value to any public official or person who has been selected to be a public official, or offers or promises any public official or any person who has been selected to be a public official to give anything of value to any other person or entity, with intent—"],[2,"(A) to influence any official act; or"],[2,"(B) to influence such public official or person who has been selected to be a public official to commit or aid in committing, or collude in, or allow, any fraud, or make opportunity for the commission of any fraud, on the United States; or"],[2,"(C) to induce such public official or such person who has been selected to be a public official to do or omit to do any act in violation of the lawful duty of such official or person;"],[1,"(2) being a public official or person selected to be a public official, directly or indirectly, corruptly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally or for any other person or entity, in return for:"],[2,"(A) being influenced in the performance of any official act;"],[2,"(B) being influenced to commit or aid in committing, or to collude in, or allow, any fraud, or make opportunity for the commission of any fraud, on the United States; or"],[2,"(C) being induced to do or omit to do any act in violation of the official duty of such official or person;"],[1,"(3) directly or indirectly, corruptly gives, offers, or promises anything of value to any person, or offers or promises such person to give anything of value to any other person or entity, with intent to influence the testimony under oath or affirmation of such first-mentioned person as a witness upon a trial, hearing, or other proceeding, before any court, any committee of either House or both Houses of Congress, or any agency, commission, or officer authorized by the laws of the United States to hear evidence or take testimony, or with intent to influence such person to absent himself therefrom;"],[1,"(4) directly or indirectly, corruptly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally or for any other person or entity in return for being influenced in testimony under oath or affirmation as a witness upon any such trial, hearing, or other proceeding, or in return for absenting himself therefrom;"],[1,"shall be fined under this title or not more than three times the monetary equivalent of the thing of value, whichever is greater, or imprisoned for not more than fifteen years, or both, and may be disqualified from holding any office of honor, trust, or profit under the United States."],[0,"(c) Whoever—"],[1,"(1) otherwise than as provided by law for the proper discharge of official duty—"],[2,"(A) directly or indirectly gives, offers, or promises anything of value to any public official, former public official, or person selected to be a public official, for or because of any official act performed or to be performed by such public official, former public official, or person selected to be a public official; or"],[2,"(B) being a public official, former public official, or person selected to be a public official, otherwise than as provided by law for the proper discharge of official duty, directly or indirectly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of any official act performed or to be performed by such official or person;"],[1,"(2) directly or indirectly, gives, offers, or promises anything of value to any person, for or because of the testimony under oath or affirmation given or to be given by such person as a witness upon a trial, hearing, or other proceeding, before any court, any committee of either House or both Houses of Congress, or any agency, commission, or officer authorized by the laws of the United States to hear evidence or take testimony, or for or because of such person's absence therefrom;"],[1,"(3) directly or indirectly, demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of the testimony under oath or affirmation given or to be given by such person as a witness upon any such trial, hearing, or other proceeding, or for or because of such person's absence therefrom;"],[1,"shall be fined under this title or imprisoned for not more than two years, or both."],[0,"(d) Paragraphs (3) and (4) of subsection (b) and paragraphs (2) and (3) of subsection (c) shall not be construed to prohibit the payment or receipt of witness fees provided by law, or the payment, by the party upon whose behalf a witness is called and receipt by a witness, of the reasonable cost of travel and subsistence incurred and the reasonable value of time lost in attendance at any such trial, hearing, or proceeding, or in the case of expert witnesses, a reasonable fee for time spent in the preparation of such opinion, and in appearing and testifying."],[0,"(e) The offenses and penalties prescribed in this section are separate from and in addition to those prescribed in sections 1503, 1504, and 1505 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/201?type=usc&year=mostrecent&link-type=html"},"by":{"1":"26, 28"},"q":[{"src":"opinion","who":"Justice Barrett, concurring in part","text":"for or because of any offcial act.","cite":"18 U. S. C. § 201(c)"},{"src":"argument","who":"Mr. Dreeben","text":"The Office of Legal Counsel has said the offense of bribery, of course, applies to the president. It does not name the president, Justice Gorsuch. Section 201 does not specifically name the president."},{"src":"argument","who":"Mr. Dreeben","text":"I think, if there was such a well-received understanding that presidents are not included in general federal criminal law unless the president is specifically named, which he is not in Section 201, Justice Scalia would have thought of that and some member of the Court would have reacted, and none did."}]},{"t":"usc","label":"18 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/18/202","subs":["(c)"],"by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 227","url":"https://www.law.cornell.edu/uscode/text/18/227","by":{"1":"25","2":"21"}},{"t":"usc","label":"18 U.S.C. § 607","url":"https://www.law.cornell.edu/uscode/text/18/607","subs":["(a)(1)"],"by":{"1":"25","2":"21"},"q":[{"src":"brief","b":1,"text":"in any room or building occupied in the discharge of official duties.","cite":"18 U.S.C. 607(a)(1)"}]},{"t":"usc","label":"18 U.S.C. § 1111","url":"https://www.law.cornell.edu/uscode/text/18/1111","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 2381","url":"https://www.law.cornell.edu/uscode/text/18/2381","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 2384","url":"https://www.law.cornell.edu/uscode/text/18/2384","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 1913","url":"https://www.law.cornell.edu/uscode/text/18/1913","stext":{"head":"§1913. Lobbying with appropriated moneys","paras":[[0,"No part of the money appropriated by any enactment of Congress shall, in the absence of express authorization by Congress, be used directly or indirectly to pay for any personal service, advertisement, telegram, telephone, letter, printed or written matter, or other device, intended or designed to influence in any manner a Member of Congress, a jurisdiction, or an official of any government, to favor, adopt, or oppose, by vote or otherwise, any legislation, law, ratification, policy, or appropriation, whether before or after the introduction of any bill, measure, or resolution proposing such legislation, law, ratification, policy, or appropriation; but this shall not prevent officers or employees of the United States or of its departments or agencies from communicating to any such Member or official, at his request, or to Congress or such official, through the proper official channels, requests for any legislation, law, ratification, policy, or appropriations which they deem necessary for the efficient conduct of the public business, or from making any communication whose prohibition by this section might, in the opinion of the Attorney General, violate the Constitution or interfere with the conduct of foreign policy, counter-intelligence, intelligence, or national security activities. Violations of this section shall constitute violations of section 1352(a) of title 31."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1913?type=usc&year=mostrecent&link-type=html"},"by":{"1":"28"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"be construed to prohibit the President or executive branch agencies from engaging in a general open dialogue with the public on the Administration's programs and policies.","cite":"18 U. S. C. § 1913"}]},{"t":"reg","label":"64 Fed. Reg. 37,038","url":"https://www.govinfo.gov/link/fr/64/37038","by":{"1":"21"}},{"t":"case","label":"Hunter v. Bryant","cite":"502 U.S. 224","y":1991,"id":"1991/90-1440","sc":1,"by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"stresse[s] the importance of resolving immunity questions at the earliest possible stage in litigation.","cite":"502 U.S. 224, 227"}]},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"by":{"2":"19"},"q":[{"src":"brief","b":2,"text":"on the Government’s discretion to protect against overzealous prosecutions ... .","cite":"579 U.S. 550, 576"}]},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"by":{"2":"4"},"q":[{"src":"brief","b":2,"text":"a carefully crafted system of checked and balanced power within each Branch.","cite":"488 U.S. 361, 381"}]},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"by":{"2":"24"},"q":[{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"provides vital assistance to [him] in the performance of [his] constitutional duty to `preserve, protect, and defend the Constitution.'","cite":"472 U. S. 511, 520"},{"src":"argument","who":"Mr. Sauer","text":"And if not or it can't be determined, then there would be a factual proceeding. And all of that under Mitchell against Forsyth and so forth would have to occur before any other proceedings in the District."}]},{"t":"case","label":"Perez v. Mortg. Bankers Ass’n","cite":"575 U.S. 92","y":2015,"id":"2014/13-1041","sc":1,"by":{"2":"4"}},{"t":"case","label":"Perrin v. United States","cite":"444 U.S. 37","y":1979,"id":"1979/78-959","sc":1,"by":{"2":"14"}},{"t":"case","label":"Tenney v. Brandhove","cite":"341 U.S. 367","y":1951,"id":"scdb/1950-081","sc":1,"by":{"2":"23"},"q":[{"src":"brief","b":2,"text":"would be of little value if [immune officials] could be subjected to … the hazard of a judgment against them based upon a jury’s speculation as to motives.","cite":"341 U.S. 367, 377"}]},{"t":"case","label":"United States v. Brewster","cite":"408 U.S. 501","y":1972,"id":"1971/70-45","sc":1,"by":{"2":"11, 14, 21, 23-24"},"q":[{"src":"brief","b":2,"text":"has enabled reckless men to slander and even destroy others with impunity, but that was the conscious choice of the Framers.","cite":"408 U.S. 501, 516"},{"src":"brief","b":2,"text":"the motivation for actual performance of [official] acts.","cite":"408 U.S. at 509"},{"src":"argument","who":"Mr. Sauer","text":"That, I think, would fall under this Court's discussion in Brewster, where the Court held with respect to legislative acts that bribery is not an official act, which also matches the court -- common law background."},{"src":"argument","who":"Mr. Sauer","text":"Again, it -- I -- I think Brewster and Johnson do address that or very persuasively at least in a slightly different context. Brewster and Johnson say the indictment has to be expunged of all the immune official acts, so there has to be a determination what's official, what's not official, and --"},{"src":"argument","who":"Mr. Sauer","text":"And the Court should remand or -- or address itself but remand for a Brewster-like determination, which is what's official and what's private."}]},{"t":"case","label":"United States v. Chaplin","cite":"54 F. Supp. 926","y":1944,"court":"S.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./54/926/","by":{"2":"14"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"by":{"2":"1, 19"},"q":[{"src":"brief","b":2,"text":"Not to worry, the Government says.","cite":"559 U.S. 460, 480"},{"src":"brief","b":2,"text":"[t]his prosecution is itself evidence of the danger in putting faith in government representations of prosecutorial restraint.","cite":"559 U.S. at 480"}]},{"t":"case","label":"Vt. Agency of Nat. Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"by":{"2":"20"},"q":[{"src":"brief","b":2,"text":"longstanding interpretive presumption that ‘person’ does not include the sovereign.","cite":"529 U.S. 765, 780"}]},{"t":"case","label":"Will v. Mich. Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"by":{"2":"20"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"2":"7"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","by":{"2":"20"},"q":[{"src":"argument","who":"Mr. Sauer","text":"The source of the immunity is principally rooted in the Executive Vesting Clause of Article II, Section 1."}]},{"t":"usc","label":"8 U.S.C. § 1324","url":"https://www.law.cornell.edu/uscode/text/8/1324","subs":["(a)(1)(A)(iv)"],"by":{"2":"17"},"q":[{"src":"brief","b":2,"text":"encourage[] or induce[] … alien[s] to come to, enter, or reside in the United States, knowing or in reckless disregard of the fact that such coming to, entry, or residence is … in violation of law,","cite":"8 U.S.C. § 1324(a)(1)(A)(iv)"}]},{"t":"usc","label":"18 U.S.C. § 1119","url":"https://www.law.cornell.edu/uscode/text/18/1119","subs":["(b)"],"by":{"2":"17"}}]};